document.addEventListener("DOMContentLoaded",(function(){document.querySelectorAll(".input-box").forEach((e=>{e.querySelector(".password_toggle_icon")?.addEventListener("click",(function(t){let o=e.querySelector("input");"password"===o.getAttribute("type")?o.setAttribute("type","text"):o.setAttribute("type","password"),e.querySelector(".inactive").classList.toggle("d-none"),e.querySelector(".active").classList.toggle("d-none")}))}))}));